Create the file `/Users/steve.briggs/projects/operations/terraform/iac-library/aws/storage/database-tools-db/variables.tf` with this exact content:

```hcl
# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# ---------------------------------------------------------------------------------------------------------------------

variable "env" {
  description = "The environment (dev, staging, prod)"
  type        = string
  validation {
    condition     = var.env != null && var.env != ""
    error_message = "Env must be set"
  }
}

variable "vpc_id" {
  description = "The ID of the VPC the RDS instance will be deployed into"
  type        = string
}

variable "private_subnet_ids" {
  description = "List of private subnets in the VPC for the RDS Subnet Group"
  type        = list(string)
}

variable "trusted_cidr_blocks" {
  description = "CIDR blocks allowed to access the RDS instance on port 5432"
  type        = list(string)
}

variable "pg_version" {
  description = "Postgres database version prefix"
  type        = string
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# ---------------------------------------------------------------------------------------------------------------------

variable "name" {
  description = "The name of the RDS instance. Defaults to tools-database-<env>"
  type        = string
  default     = ""
}

variable "db_name" {
  description = "Database name to create when creating the DB instance"
  type        = string
  default     = ""
}

variable "admin_username" {
  description = "Database admin user"
  type        = string
  default     = "immuta_postgres"
}

variable "rds_instance_size" {
  description = "RDS instance size"
  type        = string
  default     = "db.t4g.small"
}

variable "allocated_storage" {
  description = "Initial storage allocated in GiB"
  type        = number
  default     = 20
}

variable "max_allocated_storage" {
  description = "Upper limit for storage autoscaling in GiB"
  type        = number
  default     = 50
}

variable "storage_encrypted" {
  description = "Whether to encrypt the RDS instance"
  type        = bool
  default     = true
}

variable "storage_type" {
  description = "Storage type of the RDS instance"
  type        = string
  default     = "gp3"
}

variable "encrypt_replicas" {
  description = "Whether to encrypt backup replicas"
  type        = bool
  default     = true
}

variable "multi_az" {
  description = "Deploy the RDS instance as multi-AZ"
  type        = bool
  default     = false
}

variable "final_snapshot" {
  description = "Take a final snapshot before destroying the DB instance"
  type        = bool
  default     = false
}

variable "backup_retention_period" {
  description = "Days to retain backups (0-35)"
  type        = number
  default     = 21
}

variable "replica_retention_period" {
  description = "Days to retain backup replicas (0-35)"
  type        = number
  default     = 21
}

variable "enhanced_monitoring_enabled" {
  description = "Enable enhanced monitoring"
  type        = bool
  default     = true
}

variable "performance_insights_enabled" {
  description = "Enable performance insights"
  type        = bool
  default     = true
}

variable "kms_key_deletion_window_in_days" {
  description = "Days to retain KMS key after deletion"
  type        = number
  default     = 30
}

variable "subnet_group_name_override" {
  description = "Override for subnet group name"
  type        = string
  default     = ""
}

variable "dba_security_group_name_override" {
  description = "Override for external access SG name"
  type        = string
  default     = ""
}

variable "security_group_name_override" {
  description = "Override for local access SG name"
  type        = string
  default     = ""
}

variable "ca_cert_identifier" {
  description = "RDS CA cert identifier"
  type        = string
  default     = "rds-ca-rsa2048-g1"
}

variable "parameters" {
  description = "A map of DB parameters to apply via a parameter group. If empty, the default parameter group is used"
  type        = set(map(string))
  default     = []
}

variable "vault_secret_path" {
  description = "Vault KV path to store admin credentials"
  type        = string
  default     = "platform/tools-database"
}

variable "tags" {
  description = "Tags to apply to created resources"
  type        = map(string)
  default     = {}
}
```

Then verify formatting:
```bash
cd /Users/steve.briggs/projects/operations/terraform/iac-library/aws/storage/database-tools-db
terraform fmt -check variables.tf
```

Run `terraform fmt variables.tf` to fix any diffs, then re-check.

End with `STATUS: DONE` or `STATUS: BLOCKED`.

